 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/event.h>
#include <nuttx/irq.h>
#include <nuttx/semaphore.h>
#include <nuttx/queue.h>

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int nxevent_post(FAR nxevent_t *event, nxevent_mask_t events,
                 unsigned int flags)
{
  FAR struct dq_entry_s *node;
  FAR struct dq_entry_s *next;
  irqstate_t irqflags;

  irqflags = enter_critical_section();

  /* OR in the new event bits */

  event->events |= events;

  /* Wake up any waiters whose conditions are now satisfied */

  for (node = dq_peek(&event->list); node != NULL; node = next)
    {
      FAR struct nxevent_waiter_s *waiter =
        (FAR struct nxevent_waiter_s *)node;

      next = dq_next(node);

      if (waiter->mask == 0)
        {
          /* mask == 0 means wait for ANY event */

          if (event->events != 0)
            {
              waiter->result = event->events;
              event->events = 0;
              dq_rem(node, &event->list);
              nxsem_post(&waiter->sem);
            }
        }
      else if (waiter->flags & NXEVENT_WAIT_ALL)
        {
          /* Wait for ALL bits in mask */

          if ((event->events & waiter->mask) == waiter->mask)
            {
              waiter->result = event->events & waiter->mask;
              event->events &= ~waiter->mask;
              dq_rem(node, &event->list);
              nxsem_post(&waiter->sem);
            }
        }
      else
        {
          /* Wait for ANY bit in mask */

          if ((event->events & waiter->mask) != 0)
            {
              waiter->result = event->events & waiter->mask;
              event->events &= ~waiter->result;
              dq_rem(node, &event->list);
              nxsem_post(&waiter->sem);
            }
        }
    }

  leave_critical_section(irqflags);
  return 0;
}
ENDOFFILE"}

